"""Create charts from analysis_outputs generated by Data_analysis.py."""
from pathlib import Path
import pandas as pd
import matplotlib.pyplot as plt

ROOT = Path(__file__).resolve().parent
DATA = ROOT / "analysis_outputs"
OUT = ROOT / "charts_generated"
OUT.mkdir(exist_ok=True)

def save_bar(series, title, xlabel, ylabel, filename, horizontal=False):
    if series.empty:
        return
    ax = series.plot(kind="barh" if horizontal else "bar", figsize=(10, 6), title=title)
    ax.set_xlabel(xlabel)
    ax.set_ylabel(ylabel)
    plt.tight_layout()
    plt.savefig(OUT / filename, dpi=160)
    plt.close()

def main():
    district_file = DATA / "district_summary.csv"
    if district_file.exists():
        d = pd.read_csv(district_file, index_col=0)
        if "Total_Visitors" in d:
            save_bar(d["Total_Visitors"].nlargest(10).sort_values(), "Top 10 Districts by Visitors",
                     "Visitors", "District", "top_districts.png", horizontal=True)

    monthly_file = DATA / "monthly_summary.csv"
    if monthly_file.exists():
        m = pd.read_csv(monthly_file)
        if "Total_Visitors" in m and {"Year", "Month_Number"}.issubset(m.columns):
            m["Period"] = m["Year"].astype(int).astype(str) + "-" + m["Month_Number"].astype(int).astype(str).str.zfill(2)
            ax = m.sort_values(["Year", "Month_Number"]).plot(x="Period", y="Total_Visitors",
                    figsize=(12, 5), marker="o", title="Monthly Tourism Visitors", legend=False)
            ax.set_xlabel("Month")
            ax.set_ylabel("Visitors")
            plt.xticks(rotation=45)
            plt.tight_layout()
            plt.savefig(OUT / "monthly_visitors.png", dpi=160)
            plt.close()

    if district_file.exists():
        d = pd.read_csv(district_file)
        if {"Domestic_Visitors", "Foreign_Visitors"}.issubset(d.columns):
            d = d.set_index("District")
            ax = d[["Domestic_Visitors", "Foreign_Visitors"]].nlargest(10, "Domestic_Visitors").plot(
                kind="bar", figsize=(11, 6), title="Domestic vs Foreign Visitors by District")
            ax.set_xlabel("District")
            ax.set_ylabel("Visitors")
            plt.xticks(rotation=45)
            plt.tight_layout()
            plt.savefig(OUT / "domestic_vs_foreign.png", dpi=160)
            plt.close()
    print(f"Charts saved in: {OUT}")

if __name__ == "__main__":
    main()
